-5156-bf15-15dfe19bb2f5"},{"id":"f2f87b90-3eaa-51ac-96a6-a5a1709f1153","atual":"1dd9c2af-882a-583f-a683-3c4a6beff4e9"},{"id":"efd273c9-f90c-5b5c-93a9-efccc3957f26","atual":"e5644672-4a13-5f27-b55c-a298a7e77c55"},{"id":"99972a8b-c5ec-5c88-9c8e-79dc80978d77","atual":"2bfe76f4-b44d-53c5-bbd3-00a1e3316b09"},{"id":"d74e84cc-11cb-5b61-8ce3-dd8de04335f7","atual":"75aacde6-bff0-5da1-948f-dbffcc1b844c"},{"id":"f5cef8ca-ae29-588f-9d66-72e457f0e3c4","atual":"5fff599d-6e57-5746-a390-eaa6109e9e0c"}]'::jsonb) AS src(id text, atual text)
