    AND (SELECT count(*) FROM "QuestaoQuiz" q WHERE q."quizId" = atual.id) >= 10;

  INSERT INTO "CenarioPhishing" (id, titulo, descricao, "conteudoMensagem", tipo, "ehPhishing", explicacao, "aulaId", status, "criadoEm", "atualizadoEm")
  SELECT src.id, src.titulo, src.descricao, src."conteudoMensagem", src.tipo::"TipoCenarioPhishing", src."ehPhishing", src.explicacao, src."aulaId", 'PUBLICADO'::"StatusAtividade", now(), now()
  FROM jsonb_to_recordset('[{"id":"11aed192-b238-5731-9c65-f8b948419d39","titulo":"Sua conta será bloqueada","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"De: Equipe de acesso <suporte@conta-verificar.invalid>\nAssunto: Bloqueio em 10 minutos\n\nSua conta será suspensa. Envie sua senha e o código de verificação para evitar o bloqueio. Não contate o suporte habitual.","tipo":"EMAIL","ehPhishing":true,"explicacao":"O cenário combina urgência, pedido de senha e código, além de desencorajar a confirmação independente. Não responda com credenciais.","aulaId":"3a076ebe-5b2c-5c52-b776-abaf63112615"},{"id":"d85d58cd-bbe5-5972-8b2c-614ca3952f1f","titulo":"Uma entrega pendente","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Entrega retida! Pague agora a taxa no endereço entrega-pendente.invalid para liberar seu pacote. Prazo: 15 minutos.","tipo":"SMS","ehPhishing":true,"explicacao":"A pressão e a cobrança inesperada pedem verificação. Consulte a entrega pelo aplicativo ou site oficial, sem usar o endereço recebido.","aulaId":"87a28b69-c2c9-5931-83bb-7b8f0fcf4347"},{"id":"e5d3d987-a206-597a-a056-a81a3ab2fda5","titulo":"Aviso de reunião","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Cenário: você acabou de combinar uma reunião no sistema interno.\n\nDe: agenda@empresa.example\nSua reunião está confirmada para amanhã às 10h. Os detalhes já estão disponíveis no calendário interno. Nenhuma ação é necessária.","tipo":"EMAIL","ehPhishing":false,"explicacao":"No contexto fictício apresentado, o aviso corresponde a uma ação esperada e não solicita credenciais, pagamento ou acesso por endereço externo. A classificação vale para este cenário, não para todo e-mail de reunião.","aulaId":"64650b8e-0750-536f-9d05-45ed19e614bc"},{"id":"7e3b12bb-3ce8-5c93-9d03-d13a92f03531","titulo":"Você ganhou um prêmio","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Perfil: Promoções Oficiais 2026\nParabéns! Você foi selecionado sem inscrição. Para receber o prêmio, envie foto do documento e pague a taxa de liberação por mensagem privada.","tipo":"REDE_SOCIAL","ehPhishing":true,"explicacao":"Prêmio inesperado com cobrança e pedido de documento é um forte sinal de fraude. Um nome de perfil com a palavra oficial não comprova identidade.","aulaId":"6351f969-5122-57ed-8718-a8ea913d922c"},{"id":"5a457b64-e32f-546c-9687-543607d219d6","titulo":"Página de acesso alternativa","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Endereço apresentado: login.empresa.example.validacao.invalid\n\nPortal corporativo\nDigite sua senha e o código do autenticador. Se o navegador alertar sobre segurança, ignore e continue.","tipo":"SITE","ehPhishing":true,"explicacao":"O endereço termina em validacao.invalid; empresa.example aparece apenas no início. A instrução para ignorar avisos e fornecer o código reforça a suspeita.","aulaId":"50b1bd50-1ad5-538b-8ce5-adc972380da3"},{"id":"46f4b61e-4b2a-54c9-8385-5ab5ced94c8b","titulo":"Compartilhe o código","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Olá, sou do suporte. Um código vai chegar no seu celular. Envie para mim para cancelar um acesso indevido. Não abra o aplicativo enquanto resolvo.","tipo":"SMS","ehPhishing":true,"explicacao":"Códigos de verificação autorizam ações. Pedir o código sob o pretexto de cancelar um acesso é engenharia social. Procure o suporte pelo canal oficial.","aulaId":"0d999384-181b-5836-96a1-8bc2ff531a62"},{"id":"c1bd8a6b-599b-559e-9c49-115772f40b28","titulo":"Recibo de compra esperada","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Contexto: você concluiu uma compra no aplicativo oficial há um minuto.\nDe: recibos@loja.example\nPedido 123 confirmado. O recibo está na área de pedidos do aplicativo. Esta mensagem não solicita pagamento adicional nem contém anexos.","tipo":"EMAIL","ehPhishing":false,"explicacao":"A mensagem está alinhada ao contexto fornecido e orienta a consulta no aplicativo já utilizado. A ausência de links não garante legitimidade em qualquer situação, mas aqui não há tentativa de captura.","aulaId":"5cbd71db-6866-519d-a124-57afec3b80c8"},{"id":"0338b7c8-85ae-505c-b98e-35ce1c0e9a9c","titulo":"Um amigo em outro número","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Sou eu, troquei de número e não consigo falar agora. Preciso de uma transferência urgente para outra pessoa. Não ligue, estou em reunião.","tipo":"REDE_SOCIAL","ehPhishing":true,"explicacao":"A troca de contato, a urgência e a recusa em confirmar por voz são sinais de fraude por personificação. Confirme com o contato antigo ou outro canal conhecido.","aulaId":"8ffcd150-9fe4-55af-a9b5-5c4e670c6b2c"},{"id":"10a7ba87-d2cf-557f-801e-386f9fbec4d0","titulo":"Mudança de conta do fornecedor","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"De: financeiro@fornecedor-pagamentos.invalid\nAssunto: Nova conta para o contrato em andamento\nConhecemos o número do seu pedido. Atualize os dados bancários hoje e mantenha esta mudança fora do fluxo habitual de aprovação.","tipo":"EMAIL","ehPhishing":true,"explicacao":"Dados de um contrato não comprovam a identidade do remetente. A tentativa de contornar aprovação e mudar a conta exige confirmação independente com o fornecedor.","aulaId":"3a076ebe-5b2c-5c52-b776-abaf63112615"},{"id":"074498c7-89c2-524a-8261-9491616071df","titulo":"Permissões além da necessidade","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Convite para visualizar um documento\n\nO aplicativo Leitor Express solicita: ler todos os seus e-mails, enviar mensagens em seu nome e manter acesso permanente. Confirme para visualizar uma única página.","tipo":"SITE","ehPhishing":true,"explicacao":"O pedido usa a visualização de um documento como pretexto para obter permissões muito mais amplas. Avalie o consentimento e confirme a procedência do aplicativo.","aulaId":"87a28b69-c2c9-5931-83bb-7b8f0fcf4347"},{"id":"cd0432fa-6a6c-59fd-8ee1-68ee8803cd93","titulo":"Resposta a chamado conhecido","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Contexto: você abriu o chamado 456 no portal oficial e retornou ao mesmo portal digitando o endereço conhecido.\n\nO atendimento informa que a manutenção foi concluída. Não solicita senha, código, instalação ou acesso remoto.","tipo":"EMAIL","ehPhishing":false,"explicacao":"O contexto define uma consulta feita no canal oficial e ligada a um chamado iniciado por você. Nenhum pedido de captura aparece neste cenário.","aulaId":"64650b8e-0750-536f-9d05-45ed19e614bc"},{"id":"418613c3-e39b-5be0-9ee3-c4ab1eba04b9","titulo":"Entrevista com instalação obrigatória","descricao":"Leia o cenário e analise a origem, o contexto e o pedido antes de decidir.","conteudoMensagem":"Recrutador: para a entrevista, baixe nosso avaliador por mensagem. Desative a proteção do computador para ele funcionar. Não temos site nem processo de confirmação.","tipo":"REDE_SOCIAL","ehPhishing":true,"explicacao":"Pedir instalação por mensagem e desativação de proteção é um forte sinal de risco. Verifique a empresa e o processo por canais independentes.","aulaId":"6351f969-5122-57ed-8718-a8ea913d922c"}]'::jsonb) AS src(id text, titulo text, descricao text, "conteudoMensagem" text, tipo text, "ehPhishing" boolean, explicacao text, "aulaId" text)
  JOIN "Aula" a ON a.id = src."aulaId"
  ON CONFLICT DO NOTHING;

  INSERT INTO "CategoriaSimulacao" (id, nome, descricao, "criadoEm")
  SELECT src.id, src.nome, src.descricao, now()
  FROM jsonb_to_recordset('[{"id":"53491915-5e75-46a7-a149-cc6d91019f7f","nome":"Contas e acesso","descricao":"Situações fictícias para praticar decisões sobre contas e acesso."},{"id":"5fd37de3-a23a-493b-ac27-710a5e50d1df","nome":"Dispositivos","descricao":"Situações fictícias para praticar decisões sobre dispositivos."},{"id":"3eb19c3f-9d71-4f1a-af76-740402fcc80a","nome":"Privacidade","descricao":"Situações fictícias para praticar decisões sobre privacidade."},{"id":"145fb22a-a0e6-4701-a0e1-31b378d63eca","nome":"Redes e conexões","descricao":"Situações fictícias para praticar decisões sobre redes e conexões."},{"id":"b37504a0-bce2-4b92-a96c-f96c0c27ff92","nome":"Resposta a incidentes","descricao":"Situações fictícias para praticar decisões sobre resposta a incidentes."},{"id":"5e8f5708-7575-4098-ab0e-6433e7dab0b7","nome":"Código seguro","descricao":"Situações fictícias para praticar decisões sobre código seguro."}]'::jsonb) AS src(id text, nome text, descricao text)
  ON CONFLICT DO NOTHING;

  INSERT INTO "Simulacao" (id, titulo, descricao, nivel, "duracaoMinutos", "categoriaId", "criadoEm")
  SELECT src.id, src.titulo, src.descricao, src.nivel::"NivelTrilha", src."duracaoMinutos", categoria.id, now()
  FROM jsonb_to_recordset('[{"id":"92ba3928-9f53-45ba-a9ee-e514925abc1a","titulo":"Um acesso que não foi você","descricao":"Uma entrada desconhecida aparece na sua conta. Decida como proteger seu acesso, passo a passo.","nivel":"BASICO","duracaoMinutos":5,"categoria":"Contas e acesso"},{"id":"f03c90e8-1ef9-4952-a62b-9adb09a6fe54","titulo":"A conta de quem mudou de equipe","descricao":"Revise permissões de uma equipe fictícia sem interromper acessos que ainda são necessários.","nivel":"INTERMEDIARIO","duracaoMinutos":6,"categoria":"Contas e acesso"},{"id":"1fe46a8d-5ad6-4176-af05-177ab722e38d","titulo":"Antes de instalar, decida","descricao":"Um aplicativo promete facilitar sua rotina. Confira a origem, os pedidos de acesso e as atualizações.","nivel":"BASICO","duracaoMinutos":4,"categoria":"Dispositivos"},{"id":"d3555051-90a4-468e-a8e4-442d2c30cdb4","titulo":"Os arquivos pararam de abrir","descricao":"Pratique a primeira resposta a um possível programa malicioso em um computador fictício.","nivel":"INTERMEDIARIO","duracaoMinutos":6,"categoria":"Dispositivos"},{"id":"e652feff-79cf-48e2-a8d5-e68d6ea01d37","titulo":"Compartilhar sem expor","descricao":"Escolha o que aparece em uma publicação e para quem ela será mostrada, usando exemplos fictícios.","nivel":"BASICO","duracaoMinutos":4,"categoria":"Privacidade"},{"id":"088df616-4353-4768-a85a-6f7b320a1e48","titulo":"Quem pode entrar nessa pasta?","descricao":"Ajuste o compartilhamento de documentos em um espaço de trabalho fictício.","nivel":"INTERMEDIARIO","duracaoMinutos":5,"categoria":"Privacidade"},{"id":"eff4da34-3b54-4315-a817-2326d48a00de","titulo":"Conectar fora de casa","descricao":"Compare redes e pedidos de conexão em uma cafeteria fictícia, sem alterar seu aparelho.","nivel":"BASICO","duracaoMinutos":4,"categoria":"Redes e conexões"},{"id":"138fa967-6c87-469e-a29f-b8e74d4f1e58","titulo":"Visitantes na rede da equipe","descricao":"Separe acessos e revise configurações de uma pequena rede fictícia.","nivel":"INTERMEDIARIO","duracaoMinutos":6,"categoria":"Redes e conexões"},{"id":"7e850d4a-8108-428a-a866-12265f1de9b1","titulo":"Depois do clique, o que fazer?","descricao":"Organize a reação a uma possível exposição de credenciais, com decisões sobre acesso e comunicação.","nivel":"INTERMEDIARIO","duracaoMinutos":6,"categoria":"Resposta a incidentes"},{"id":"b402bfab-9b96-429a-af57-7c466857d00f","titulo":"Do alerta à contenção","descricao":"Correlacione registros, contenha uma credencial exposta e valide a recuperação de um serviço fictício.","nivel":"AVANCADO","duracaoMinutos":8,"categoria":"Resposta a incidentes"},{"id":"37da5607-6fb1-46d0-a6cf-9e512e4bd2eb","titulo":"Um pedido, outro usuário","descricao":"Revise uma API fictícia e corrija uma falha de autorização sem executar código fora do site.","nivel":"AVANCADO","duracaoMinutos":7,"categoria":"Código seguro"},{"id":"c90ac231-531f-4b01-acc8-b6cf2e34404f","titulo":"Entrada, consulta e registro","descricao":"Analise uma busca fictícia e ajuste consulta, validação e logs sem expor dados.","nivel":"AVANCADO","duracaoMinutos":7,"categoria":"Código seguro"}]'::jsonb) AS src(id text, titulo text, descricao text, nivel text, "duracaoMinutos" integer, categoria text)
  JOIN "CategoriaSimulacao" categoria ON categoria.nome = src.categoria
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS novas_simulacoes = ROW_COUNT;

  WITH inseridas AS (
  INSERT INTO "QuestaoSimulacao" (id, "simulacaoId", ordem, enunciado, contexto, explicacao)
  SELECT src.id, src."simulacaoId", src.ordem, src.enunciado, src.contexto, src.explicacao
  FROM jsonb_to_recordset('[{"id":"81db5d5a-2c95-4941-a43e-8ab678ea0c51","simulacaoId":"92ba3928-9f53-45ba-a9ee-e514925abc1a","ordem":0,"enunciado":"Por onde você começa?","contexto":"Minha conta fictícia\nEntrada recente: aparelho desconhecido\nHorário: 03:14\nVocê não usou a conta nesse horário.","explicacao":"Abra o próprio serviço pelo caminho conhecido. Um aviso pode ser falso, e o fato de a conta ainda abrir não descarta uma entrada indevida."},{"id":"398e26e9-a543-404f-a598-9001b7465357","simulacaoId":"92ba3928-9f53-45ba-a9ee-e514925abc1a","ordem":1,"enunciado":"Você confirmou que não reconhece o aparelho. Qual ação ajuda agora?","contexto":"Área de segurança fictícia\nSeu aparelho: conectado\nAparelho desconhecido: conectado\nOpção disponível: encerrar esse acesso","explicacao":"Encerrar o acesso impede que aquela entrada continue ativa. Uma senha diferente reduz o risco de que uma senha vazada em outro serviço abra esta conta."},{"id":"2fe36c16-3225-4680-a703-58decfcc95d5","simulacaoId":"92ba3928-9f53-45ba-a9ee-e514925abc1a","ordem":2,"enunciado":"O que falta revisar?","contexto":"Revisão da conta fictícia\nConfirmação extra de entrada: desativada\nE-mail de recuperação: antigo\nSenha: atualizada","explicacao":"A confirmação extra dificulta novas entradas indevidas. A recuperação precisa apontar para um meio que você controla; ela ajuda se o acesso for perdido."},{"id":"ef932cb3-b3fe-4d90-adea-e2573460d3c7","simulacaoId":"f03c90e8-1ef9-4952-a62b-9adb09a6fe54","ordem":0,"enunciado":"Qual ajuste segue o princípio do menor privilégio?","contexto":"Painel de acessos fictício\nPessoa: Marina\nEquipe anterior: Financeiro\nEquipe atual: Atendimento\nPermissões: Atendimento + aprovar pagamentos","explicacao":"Menor privilégio significa conceder somente o necessário. Mudanças de função exigem revisão para evitar acúmulo de permissões."},{"id":"47d7e764-a470-45da-a91a-aaf0ce37e65c","simulacaoId":"f03c90e8-1ef9-4952-a62b-9adb09a6fe54","ordem":1,"enunciado":"Como evitar que a troca de equipe mantenha uma dependência insegura?","contexto":"Automação fictícia\nUm relatório usa a conta pessoal de Marina.\nA senha dessa conta foi compartilhada com dois colegas.","explicacao":"Uma identidade própria para a automação separa acessos humanos e automatizados. As credenciais devem ter responsáveis e um caminho de atualização controlado."},{"id":"7d3a5818-09c9-43a4-a913-28a2d9f952dc","simulacaoId":"f03c90e8-1ef9-4952-a62b-9adb09a6fe54","ordem":2,"enunciado":"Qual verificação completa a mudança?","contexto":"Revisão concluída no ambiente fictício\nPermissão antiga: removida\nAutomação: identidade própria\nAinda há sessões antigas abertas.","explicacao":"Sessões e autorizações de aplicativos podem continuar válidas após a mudança de uma função. A revisão precisa incluir esses caminhos de acesso."},{"id":"b646ea99-ca52-4854-afcd-4d8712d2b89a","simulacaoId":"1fe46a8d-5ad6-4176-af05-177ab722e38d","ordem":0,"enunciado":"Qual caminho é mais cuidadoso?","contexto":"Celular fictício\nBusca: aplicativo de lanterna\nResultado patrocinado: baixar uma versão especial por arquivo\nLoja do aparelho: também tem opções.","explicacao":"A posição de um anúncio não comprova a origem. Use o caminho conhecido e confira o responsável pelo aplicativo; isso reduz riscos, mas não dispensa atenção."},{"id":"fcfd9b00-6373-4677-af5d-86dc5c3d1311","simulacaoId":"1fe46a8d-5ad6-4176-af05-177ab722e38d","ordem":1,"enunciado":"Como responder a esse pedido?","contexto":"Pedido de acesso fictício\nAplicativo: Lanterna Fácil\nQuer acessar: contatos, mensagens e câmera\nFunção anunciada: ligar a luz","explicacao":"Um aplicativo deve pedir somente o que precisa para funcionar. Contatos e mensagens também são informações pessoais, mesmo quando não contêm fotos."},{"id":"3cfc4698-c937-47bf-a8d8-1a0b18d6329c","simulacaoId":"1fe46a8d-5ad6-4176-af05-177ab722e38d","ordem":2,"enunciado":"Onde você faria a atualização?","contexto":"Atualização fictícia\nO sistema oferece uma atualização nas configurações.\nUma janela no navegador também oferece um instalador de atualização.","explicacao":"Atualizações pelo caminho oficial corrigem falhas e ajudam a manter o aparelho protegido. Uma janela no navegador pode apenas imitar um aviso do sistema."},{"id":"13d23771-96f8-4a80-a3d3-8ac3c991b805","simulacaoId":"d3555051-90a4-468e-a8e4-442d2c30cdb4","ordem":0,"enunciado":"Qual é a prioridade inicial?","contexto":"Computador fictício\nVários arquivos ganharam nomes estranhos.\nUma mensagem exige pagamento para recuperá-los.\nUma pasta compartilhada continua conectada.","explicacao":"O isolamento reduz a possibilidade de propagação. Conectar uma cópia de segurança a um aparelho ainda comprometido pode expor também essa cópia."},{"id":"f702a2e1-08c9-4cb7-a0eb-eb95e6551f39","simulacaoId":"d3555051-90a4-468e-a8e4-442d2c30cdb4","ordem":1,"enunciado":"Qual relato ajuda mais?","contexto":"Canal interno fictício\nA equipe pede informações sobre o incidente.\nVocê tem o horário, a mensagem exibida e o nome do arquivo aberto antes do problema.","explicacao":"Um relato com sequência e horários ajuda a equipe a investigar. Reenviar um arquivo suspeito ou apagar evidências pode ampliar o problema."},{"id":"ce3ed685-b553-4eff-a16a-0564aba6696f","simulacaoId":"d3555051-90a4-468e-a8e4-442d2c30cdb4","ordem":2,"enunciado":"Como conduzir a recuperação?","contexto":"Recuperação fictícia\nA equipe isolou a causa e preparou um ambiente limpo.\nExiste uma cópia de segurança anterior ao incidente.","explicacao":"Uma cópia precisa ser utilizável e estar livre do problema. Recuperar em ambiente limpo e validar o resultado reduz a chance de reiniciar o incidente."},{"id":"add948ea-3308-41d8-a212-3161ade96838","simulacaoId":"e652feff-79cf-48e2-a8d5-e68d6ea01d37","ordem":0,"enunciado":"O que fazer antes de publicar?","contexto":"Prévia fictícia de publicação\nFoto: mesa de estudos\nNo fundo: documento com nome e endereço\nPúblico: qualquer pessoa","explicacao":"Detalhes no fundo também podem revelar informações. Revise a imagem antes de compartilhar; apagar depois não garante que ninguém tenha feito uma cópia."},{"id":"f054eb87-7050-4155-adaf-1faf6f802b9e","simulacaoId":"e652feff-79cf-48e2-a8d5-e68d6ea01d37","ordem":1,"enunciado":"Qual versão reduz a exposição?","contexto":"Perfil fictício\nPublicação planejada: viagem de uma semana\nTexto: endereço da casa e horário em que ela ficará vazia\nPúblico: aberto","explicacao":"Combinar localização e rotina pode expor mais do que uma foto isolada. Compartilhe o necessário com um público adequado."},{"id":"578147be-e9eb-481c-a129-0a6354089db7","simulacaoId":"e652feff-79cf-48e2-a8d5-e68d6ea01d37","ordem":2,"enunciado":"Qual é uma atitude cuidadosa?","contexto":"Pedido fictício de marcação\nUma foto mostra você e outras pessoas.\nO perfil que publicou é aberto.","explicacao":"A divulgação também afeta outras pessoas. Uma publicação acessível não torna ilimitado o uso da imagem nem elimina a necessidade de cuidado."},{"id":"59ef55c1-e903-446c-a002-e1c34c3b0dee","simulacaoId":"088df616-4353-4768-a85a-6f7b320a1e48","ordem":0,"enunciado":"Qual configuração é mais adequada?","contexto":"Pasta fictícia: Atendimento\nConteúdo: solicitações de clientes\nLink: qualquer pessoa com o link pode editar\nNecessidade: duas pessoas da equipe precisam ler","explicacao":"O link pode ser encaminhado. Controle de público e de permissão deve refletir quem precisa acessar e o que cada pessoa precisa fazer."},{"id":"56fff27f-0959-4d19-af08-a042df0a8408","simulacaoId":"088df616-4353-4768-a85a-6f7b320a1e48","ordem":1,"enunciado":"Como aplicar a minimização de dados?","contexto":"Documento fictício\nColunas: nome, e-mail, pedido e dados adicionais sem relação com o atendimento\nObjetivo: organizar pedidos da semana","explicacao":"Minimização significa limitar os dados ao que é necessário para uma finalidade definida. Coletar mais por costume amplia a exposição sem melhorar necessariamente o serviço."},{"id":"f9167234-c414-4258-acfb-870a279f3f3c","simulacaoId":"088df616-4353-4768-a85a-6f7b320a1e48","ordem":2,"enunciado":"O que precisa ser revisto?","contexto":"Revisão de acessos fictícia\nProjeto: encerrado\nEx-colaborador: ainda tem acesso\nLink público antigo: ativo","explicacao":"Encerrar um projeto não revoga permissões automaticamente. Revise pessoas, links e necessidade de conservação conforme a finalidade e as regras aplicáveis."},{"id":"47617ff7-c93c-4c5f-ac28-dd57125b1652","simulacaoId":"eff4da34-3b54-4315-a817-2326d48a00de","ordem":0,"enunciado":"Como escolher a conexão?","contexto":"Redes fictícias disponíveis\nCafé da Praça\nCafé da Praça Grátis\nA placa do local só informa: pergunte a rede no balcão.","explicacao":"Nome parecido e sinal forte não comprovam a origem da rede. Confirme qual conexão o local realmente oferece."},{"id":"808e9120-d22c-45f9-a06f-9fe2cd013642","simulacaoId":"eff4da34-3b54-4315-a817-2326d48a00de","ordem":1,"enunciado":"Como agir?","contexto":"Página de conexão fictícia\nPara liberar a internet, a página pede a senha do seu e-mail pessoal.","explicacao":"Uma conexão de internet não precisa da senha da sua conta pessoal. Um pedido fora de contexto é motivo para interromper e confirmar a origem."},{"id":"2e25bfaf-b0f9-4057-a50c-946ef66eaf13","simulacaoId":"eff4da34-3b54-4315-a817-2326d48a00de","ordem":2,"enunciado":"Qual escolha reduz conexões involuntárias?","contexto":"Fim da visita fictícia\nO aparelho quer se conectar automaticamente a essa rede no futuro.","explicacao":"Conectar automaticamente pode colocar o aparelho em uma rede sem você perceber. Prefira decidir quando uma conexão fora de casa será usada."},{"id":"e55c9b5f-c9bd-4311-a1b3-167745ed4a70","simulacaoId":"138fa967-6c87-469e-a29f-b8e74d4f1e58","ordem":0,"enunciado":"Qual mudança reduz a exposição dos recursos internos?","contexto":"Mapa de rede fictício\nMesma rede: notebooks da equipe, arquivos internos e celulares de visitantes\nObjetivo: visitantes precisam apenas de internet","explicacao":"Segmentação separa grupos com necessidades diferentes. Uma rede de convidados deve oferecer a conectividade necessária sem liberar os recursos internos."},{"id":"f47f8667-ca97-4a22-a486-90a438e8c7a0","simulacaoId":"138fa967-6c87-469e-a29f-b8e74d4f1e58","ordem":1,"enunciado":"Qual conjunto de ajustes é mais adequado?","contexto":"Roteador fictício\nSenha administrativa: padrão de fábrica\nGerenciamento pela internet: ativo\nAtualização: disponível","explicacao":"A senha da rede e a senha administrativa têm funções distintas. Proteger o painel e manter o equipamento atualizado reduz caminhos de acesso indevido."},{"id":"92e2fce6-aa23-4aa3-a56d-5e71d7757668","simulacaoId":"138fa967-6c87-469e-a29f-b8e74d4f1e58","ordem":2,"enunciado":"O teste indica que a configuração está pronta?","contexto":"Teste fictício após a separação\nConvidado: acessa a internet\nConvidado: ainda abre a pasta interna\nEquipe: acessa os arquivos","explicacao":"Ter nomes diferentes não comprova isolamento. Verifique tanto o acesso que deve funcionar quanto aquele que deve ser bloqueado."},{"id":"37106f79-de2c-4c6c-a94b-3966beb1440e","simulacaoId":"7e850d4a-8108-428a-a866-12265f1de9b1","ordem":0,"enunciado":"Qual resposta é prioritária?","contexto":"Linha do tempo fictícia\n10:12: uma pessoa abriu um link recebido\n10:13: informou a senha em uma página parecida com a da empresa\n10:15: percebeu que o endereço era diferente","explicacao":"Agir cedo reduz o período de exposição. Use o serviço oficial e o canal de resposta da organização; não amplie a circulação do link suspeito."},{"id":"ec240010-384e-4051-ad5c-229faf118a4f","simulacaoId":"7e850d4a-8108-428a-a866-12265f1de9b1","ordem":1,"enunciado":"O que essa informação exige?","contexto":"Apuração fictícia\nA pessoa não sabe se aprovou uma confirmação extra de entrada.\nO painel mostra uma sessão desconhecida criada às 10:14.","explicacao":"Uma sessão pode permanecer válida mesmo após mudanças em outras credenciais. A resposta deve verificar o mecanismo do serviço e invalidar o acesso indevido."},{"id":"3b4bd4a3-f782-44cb-a310-b7cab8e64316","simulacaoId":"7e850d4a-8108-428a-a866-12265f1de9b1","ordem":2,"enunciado":"Qual conteúdo deve ser compartilhado?","contexto":"Comunicação fictícia\nA equipe pede um resumo para investigar o caso.\nHá horários, endereço da página e ações realizadas.","explicacao":"A comunicação deve apoiar a investigação e a contenção. Fatos e horários ajudam; expor a senha ou culpabilizar a pessoa pode agravar o incidente e atrasar relatos."},{"id":"6234d9ae-7b0c-43dc-a5de-873905182231","simulacaoId":"b402bfab-9b96-429a-af57-7c466857d00f","ordem":0,"enunciado":"Qual hipótese deve ser investigada primeiro?","contexto":"Registros fictícios — horário UTC\n12:01 key=svc-export origem=10.0.0.12 volume=2 MB\n12:03 key=svc-export origem=198.51.100.24 volume=900 MB\n12:04 alerta: volume fora do padrão\nInventário: svc-export deveria operar só na rede interna","explicacao":"Autenticação válida não comprova uso autorizado. A correlação entre identidade, origem, volume e escopo ajuda a formar uma hipótese verificável, sem confundir alerta com conclusão."},{"id":"df6c37f4-27a1-4ae2-a58c-d14fae16ab72","simulacaoId":"b402bfab-9b96-429a-af57-7c466857d00f","ordem":1,"enunciado":"Qual plano equilibra contenção e continuidade?","contexto":"Plano fictício de contenção\nCredencial suspeita: svc-export\nDependências: tarefa noturna e exportação manual\nAlternativa temporária: identidade com escopo reduzido","explicacao":"A contenção precisa considerar dependências e credenciais derivadas. Preservar evidências e controlar acesso aos registros permite investigar sem manter o caminho de abuso."},{"id":"d528e091-a40d-422b-a96e-88ff07ab2a7f","simulacaoId":"b402bfab-9b96-429a-af57-7c466857d00f","ordem":2,"enunciado":"Qual verificação falta antes de encerrar?","contexto":"Validação fictícia\nChave antiga: rejeitada\nNova identidade: exporta somente o conjunto permitido\nAlertas: retornaram ao padrão\nUma tentativa fora do escopo ainda precisa ser testada","explicacao":"Validação deve cobrir permissões positivas e negativas. O encerramento também depende da revisão do alcance do incidente e do monitoramento de recorrência."},{"id":"d808d1fd-d4f5-4cf9-adf2-f8778bb2aa3f","simulacaoId":"37da5607-6fb1-46d0-a6cf-9e512e4bd2eb","ordem":0,"enunciado":"Qual controle está faltando?","contexto":"Requisição fictícia\nGET /api/documentos/42\nSessão autenticada: usuarioId=18\nDocumento 42: proprietarioId=7\nHandler: buscarDocumento(params.id)","explicacao":"O servidor precisa aplicar autorização por objeto. Esconder controles ou tornar um identificador difícil de adivinhar não substitui a verificação de permissão."},{"id":"0053944e-d90c-430d-a978-6b592a6b82dd","simulacaoId":"37da5607-6fb1-46d0-a6cf-9e512e4bd2eb","ordem":1,"enunciado":"Qual alteração manteria a verificação confiável?","contexto":"Consulta fictícia\nconst documento = await db.documento.findFirst({\n  where: { id: params.id, proprietarioId: sessao.usuarioId }\n});\nO proprietário não deve vir do corpo enviado pelo cliente.","explicacao":"Validação de formato e autorização são controles diferentes. A identidade usada para autorizar deve vir do contexto autenticado do servidor, e as regras devem cobrir compartilhamentos legítimos quando existirem."},{"id":"d3b9a03d-c78b-4bfa-ad9e-70360c43021b","simulacaoId":"37da5607-6fb1-46d0-a6cf-9e512e4bd2eb","ordem":2,"enunciado":"Qual teste é indispensável?","contexto":"Casos de teste fictícios\nAcessar próprio documento: 200\nAcessar documento permitido por compartilhamento: 200\nTrocar o ID para documento de outro usuário: ainda não testado","explicacao":"Testes de autorização precisam incluir negação de acesso, diferentes identidades e operações. Uma conta privilegiada pode ocultar falhas que afetam usuários comuns."},{"id":"8350652e-41e8-415d-adb1-8ccfab346aa6","simulacaoId":"c90ac231-531f-4b01-acc8-b6cf2e34404f","ordem":0,"enunciado":"Qual mudança trata a separação entre dados e comando?","contexto":"Código fictício\nconst sql = \"SELECT * FROM pedidos WHERE nome = ''\" + entrada + \"''\";\nawait db.query(sql);","explicacao":"Parâmetros mantêm valores separados da estrutura da consulta. A validação do navegador pode ser contornada; formato, autorização e parametrização devem ser tratados no servidor."},{"id":"ff6b8ac1-171c-43c4-a886-2b272c1afdf3","simulacaoId":"c90ac231-531f-4b01-acc8-b6cf2e34404f","ordem":1,"enunciado":"Qual tratamento é apropriado?","contexto":"Validação fictícia\nCampo: quantidade\nRequisição: { quantidade: -5, usuarioId: 7 }\nSessão: usuarioId=18","explicacao":"JSON sintaticamente válido não garante uma operação válida. Regras de domínio e autorização devem ser verificadas, sem confiar em campos que tentem substituir a identidade autenticada."},{"id":"5c849e0b-2570-4190-ac29-465c98a04dc7","simulacaoId":"c90ac231-531f-4b01-acc8-b6cf2e34404f","ordem":2,"enunciado":"Como reduzir a exposição sem perder rastreabilidade?","contexto":"Log fictício proposto\nconsole.log({ senha, token, email, corpoCompleto });\nObjetivo do log: investigar uma falha de consulta","explicacao":"Logs devem registrar o necessário para investigar, com controle de acesso e conservação adequada. Senhas, tokens e conteúdo pessoal desnecessário ampliam o impacto de uma exposição."}]'::jsonb) AS src(id text, "simulacaoId" text, ordem integer, enunciado text, contexto text, explicacao text)
  JOIN "Simulacao" simulacao ON simulacao.id = src."simulacaoId"
  WHERE NOT EXISTS (SELECT 1 FROM "QuestaoSimulacao" existente WHERE existente."simulacaoId" = simulacao.id AND existente.ordem = src.ordem)
  ON CONFLICT DO NOTHING RETURNING id
  ) SELECT coalesce(array_agg(id), ARRAY[]::text[]) INTO ids_questoes_simulacao FROM inseridas;

