906-4c61-a6d1-e4b913af62f6","questaoId":"d808d1fd-d4f5-4cf9-adf2-f8778bb2aa3f","ordem":1,"texto":"Trocar o identificador numérico por um UUID e dispensar autorização.","isCorreta":false},{"id":"dfb065a3-8715-4236-a8d1-e35d015f3757","questaoId":"d808d1fd-d4f5-4cf9-adf2-f8778bb2aa3f","ordem":2,"texto":"Verificar no servidor se o usuário autenticado tem permissão para acessar o documento solicitado.","isCorreta":true},{"id":"48341086-0744-4556-a2cd-7e7794c7719f","questaoId":"0053944e-d90c-430d-a978-6b592a6b82dd","ordem":0,"texto":"Liberar o documento sempre que o parâmetro tiver formato válido.","isCorreta":false},{"id":"1b331d4c-4f0d-4bc9-a1e3-5a57f6ac6fcd","questaoId":"0053944e-d90c-430d-a978-6b592a6b82dd","ordem":1,"texto":"Derivar a identidade da sessão validada e tratar a ausência de permissão sem retornar o conteúdo.","isCorreta":true},{"id":"61cae4ef-a7c2-4550-ada3-cdf42441beec","questaoId":"0053944e-d90c-430d-a978-6b592a6b82dd","ordem":2,"texto":"Aceitar proprietarioId do cliente como prova de acesso.","isCorreta":false},{"id":"65dd6ecb-1676-4749-a20d-b4f16293493c","questaoId":"d3b9a03d-c78b-4bfa-ad9e-70360c43021b","ordem":0,"texto":"Confirmar que outro usuário não recebe o conteúdo, incluindo variações de identificador e de operação.","isCorreta":true},{"id":"82ccb537-bd41-4b99-a3e8-d19d71e6e98a","questaoId":"d3b9a03d-c78b-4bfa-ad9e-70360c43021b","ordem":1,"texto":"Testar somente se o botão existe na tela.","isCorreta":false},{"id":"294fcc4d-b93c-49a4-a4cd-c3cf14241d5f","questaoId":"d3b9a03d-c78b-4bfa-ad9e-70360c43021b","ordem":2,"texto":"Usar apenas um usuário administrador em todos os testes.","isCorreta":false},{"id":"c35be232-b618-48e9-ad81-98a23c00e191","questaoId":"8350652e-41e8-415d-adb1-8ccfab346aa6","ordem":0,"texto":"Confiar somente na validação do formulário do navegador.","isCorreta":false},{"id":"bca60065-9957-48d3-a5a3-5b0a50a8607c","questaoId":"8350652e-41e8-415d-adb1-8ccfab346aa6","ordem":1,"texto":"Usar consulta parametrizada e manter a autorização da operação no servidor.","isCorreta":true},{"id":"4e6af42e-a00b-4c11-a69f-0779e9ca9f75","questaoId":"8350652e-41e8-415d-adb1-8ccfab346aa6","ordem":2,"texto":"Concatenar a entrada após remover apenas espaços.","isCorreta":false},{"id":"623e8d11-3c3e-45b7-a01d-d0303725b7cd","questaoId":"ff6b8ac1-171c-43c4-a886-2b272c1afdf3","ordem":0,"texto":"Validar faixa e tipo da quantidade e usar a identidade da sessão, ignorando uma identidade de usuário não autorizada enviada pelo cliente.","isCorreta":true},{"id":"70c9dd46-ffa1-44cf-ad0a-342e3d0cec20","questaoId":"ff6b8ac1-171c-43c4-a886-2b272c1afdf3","ordem":1,"texto":"Aceitar qualquer número porque o JSON é válido.","isCorreta":false},{"id":"b2773646-3cdd-493b-a338-47f1e3f7687a","questaoId":"ff6b8ac1-171c-43c4-a886-2b272c1afdf3","ordem":2,"texto":"Usar usuarioId=7 porque veio no corpo da requisição.","isCorreta":false},{"id":"d6bad9ad-9578-4075-ac0d-e2891e2ca085","questaoId":"5c849e0b-2570-4190-ac29-465c98a04dc7","ordem":0,"texto":"Manter todos os segredos nos logs para facilitar o suporte.","isCorreta":false},{"id":"72f8765d-5a1d-443d-a8b4-5637ef643fa8","questaoId":"5c849e0b-2570-4190-ac29-465c98a04dc7","ordem":1,"texto":"Desativar qualquer registro de falha em todos os ambientes.","isCorreta":false},{"id":"f4df8e03-e8a8-473e-abf6-27ace7a36d85","questaoId":"5c849e0b-2570-4190-ac29-465c98a04dc7","ordem":2,"texto":"Registrar identificador de correlação, operação, horário e resultado, sem senha, token ou corpo completo desnecessário.","isCorreta":true}]'::jsonb) AS src(id text, "questaoId" text, ordem integer, texto text, "isCorreta" boolean)
  JOIN "QuestaoSimulacao" q ON q.id = src."questaoId"
  WHERE q.id = ANY(ids_questoes_simulacao)
